import type { TeamHuntState } from "@hunt/public-client";
import {
  type ResolvedCutsceneContent,
  CutsceneDisplay,
  useGlobalVolume,
} from "@hunt/puzzle-components";
import { TileRoundBody, TilesQueryClientProvider } from "@hunt/tiles";
import React, { useEffect, useRef, useState } from "react";
import { createRoot } from "react-dom/client";
import tileSolveSound from "../../../assets/solve_single_level.mp3";
import "@hunt/tiles/offset-grid.css";
import "@hunt/tiles/round-layout.css";
import { ErrataDataProvider } from "../../../client/ErrataProvider";
import useDataset from "../../../client/useDataset";
import { ErratumIcon } from "../../../components/ErratumIcon";
import type { NotificationsHandle } from "../../../components/Notifications";
import { PuzzleIcon } from "../../../components/PuzzleAndTaskDisplay/PuzzleCard";
import RoundHintLink from "../../../components/RoundHintLink";
import { type TileRoundState } from ".";

const TileRoundManager = () => {
  const initialTileState = (
    window as unknown as { initialTileState: TileRoundState }
  ).initialTileState;
  const initialTeamState = (
    window as unknown as { initialTeamState: TeamHuntState }
  ).initialTeamState;
  const initialCutsceneContent = (
    window as unknown as { initialCutsceneContent?: ResolvedCutsceneContent[] }
  ).initialCutsceneContent;

  // NOTE: useTilesAutomergeRepo removed - automerge is being eliminated
  // TileRoundBody now manages its own state via TileRoundClient

  // Use "atlas_of_mosaics_new" dataset which is a replace subscription
  // that recomputes tileRoundState from teamState using gate-based logic
  const roundState = useDataset(
    "atlas_of_mosaics_new",
    undefined,
    initialTileState,
  );
  const teamState = useDataset("team_state", undefined, initialTeamState);

  // Access notifications from navbar
  const notificationsRef = useRef<NotificationsHandle | null>(null);
  const [audio, setAudio] = useState<HTMLAudioElement | null>(null);
  const globalVolume = useGlobalVolume();

  // Get notifications handle from global window object (set by navbar)
  useEffect(() => {
    const checkNotifications = () => {
      const handle = (
        window as unknown as { tileLevelNotifications?: NotificationsHandle }
      ).tileLevelNotifications;
      if (handle) {
        notificationsRef.current = handle;
      }
    };

    checkNotifications();
    // Check periodically in case navbar hasn't initialized yet
    const interval = setInterval(checkNotifications, 100);
    return () => {
      clearInterval(interval);
    };
  }, []);

  // Handle audio playback for solve sound
  useEffect(() => {
    if (audio) {
      audio.volume = globalVolume;
      void audio.play().catch((error: unknown) => {
        console.error("Failed to play solve sound:", error);
      });

      const handleStop = () => {
        setAudio(null);
      };

      audio.onended =
        audio.onpause =
        audio.onabort =
        audio.onemptied =
        audio.onstalled =
        audio.onerror =
          handleStop;
    }
  }, [audio, globalVolume]);

  // Cleanup audio on unmount
  useEffect(() => {
    return () => {
      if (audio) {
        audio.pause();
        audio.src = "";
      }
    };
  }, [audio]);

  // Callback for when a level is solved
  const handleLevelSolved = (levelId: string, levelTitle: string) => {
    const notifications = notificationsRef.current;
    if (notifications) {
      notifications.addNotification({
        key: `tile-level-solved-${levelId}-${Date.now()}`,
        icon: <PuzzleIcon lockState="unlocked" solved />,
        description: `${levelTitle} was solved!`,
        variant: "solved",
      });

      // Play solve sound
      setAudio(new Audio(tileSolveSound));
    }
  };

  return (
    <ErrataDataProvider initialTeamState={initialTeamState}>
      <TilesQueryClientProvider>
        <TileRoundBody
          teamState={teamState}
          roundState={roundState}
          teamId={initialTileState.teamId ?? ""}
          syncServerUrl={initialTileState.syncServerUrl}
          onLevelSolved={handleLevelSolved}
          renderLevelTitleAddon={(levelId) => (
            <ErratumIcon
              resource={{ type: "tile_level", slug: levelId }}
              iconClassName="h-5 w-5 text-red-500"
            />
          )}
          hintPanel={
            <RoundHintLink
              slug="atlas_of_mosaics"
              teamState={initialTeamState}
            />
          }
        />
        <CutsceneDisplay content={initialCutsceneContent} />
      </TilesQueryClientProvider>
    </ErrataDataProvider>
  );
};

const elem = document.getElementById("atlas-round-root");
if (elem) {
  createRoot(elem).render(<TileRoundManager />);
} else {
  console.error(
    "Could not mount TileRoundManager because #atlas-round-root was nowhere to be found",
  );
}
